mapper.select:
SELECT A.*, B.* FROM ( SELECT tt1.rnum no, tt1.credit_id, tt1.content_id, tt1.person_id, tt1.role, tt1."CHARACTER" AS character, tt1.display_order FROM ( SELECT ROWNUM rnum, t1.* FROM ( SELECT * FROM content_credit
ORDER BY content_id ASC, role ASC, display_order ASC, credit_id ASC ) t1 WHERE ROWNUM <= (#{pageSize} * (#{pageNo} - 1) + #{pageSize}) ) tt1 WHERE rnum >= (#{pageSize} * (#{pageNo} - 1) + 1) ) A CROSS JOIN ( SELECT COUNT(*) total_cnt FROM content_credit
) B
